using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Staybnb.Models; using Staybnb.Services;
namespace Staybnb.Controllers;
public class AccountController(UserManager<ApplicationUser> users,SignInManager<ApplicationUser> signIn,ActivityLogger logger):Controller {
 [HttpGet] public IActionResult Register()=>View(new RegisterViewModel());
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Register(RegisterViewModel model) { if(!ModelState.IsValid)return View(model); var user=new ApplicationUser{UserName=model.Email,Email=model.Email,DisplayName=model.DisplayName}; var result=await users.CreateAsync(user,model.Password); if(result.Succeeded){await users.AddToRoleAsync(user,"Guest"); await logger.LogAsync(user.Id,"Registration","New Guest account created."); await signIn.SignInAsync(user,false); return RedirectToAction("Index","Home");} foreach(var e in result.Errors)ModelState.AddModelError("",e.Description); return View(model); }
 [HttpGet] public IActionResult Login(string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;return View(new LoginViewModel());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Login(LoginViewModel model,string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;if(!ModelState.IsValid)return View(model);var user=await users.FindByEmailAsync(model.Email);if(user==null){ModelState.AddModelError("","Invalid login attempt.");return View(model);}var result=await signIn.PasswordSignInAsync(user,model.Password,model.RememberMe,true);if(result.Succeeded){await logger.LogAsync(user.Id,"Login","Successful login.");if(Url.IsLocalUrl(returnUrl))return Redirect(returnUrl);if(await users.IsInRoleAsync(user,"SuperAdmin")||await users.IsInRoleAsync(user,"Admin"))return RedirectToAction("Index","Admin");if(await users.IsInRoleAsync(user,"Host"))return RedirectToAction("Dashboard","HostApplications");return RedirectToAction("Index","Home");}await logger.LogAsync(user.Id,"LoginFailed","Failed login attempt.");ModelState.AddModelError("",result.IsLockedOut?"Account temporarily locked. Try again later.":"Invalid login attempt.");return View(model);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Logout(){var id=users.GetUserId(User);await signIn.SignOutAsync();await logger.LogAsync(id,"Logout","User logged out.");return RedirectToAction("Index","Home");}
 public IActionResult AccessDenied()=>View();
}